svg.script:

(function() {
  const devotionNode = document.querySelector('.devotion-node');
  const devotionPanel = document.getElementById('devotion-panel');
  const closeBtn = document.getElementById('close-btn');

  const expressionNode = document.querySelector('.expression-node');
  const expressionPanel = document.getElementById('expression-panel');
  const closeBtnExpression = document.getElementById('close-btn-expression');

  const ramaNode = document.querySelector('.rama-node');
  const ramaPanel = document.getElementById('rama-panel');
  const closeBtnRama = document.getElementById('close-btn-rama');

  // Panel configuration
  const panels = [
    { node: devotionNode, panel: devotionPanel, closeBtn: closeBtn },
    { node: expressionNode, panel: expressionPanel, closeBtn: closeBtnExpression },
    { node: ramaNode, panel: ramaPanel, closeBtn: closeBtnRama }
  ];

  // Devotion panel handlers
  devotionNode.addEventListener('click', function(e) {
    e.preventDefault();
    devotionPanel.setAttribute('opacity', '1');
    devotionPanel.setAttribute('pointer-events', 'all');
  });

  // Expression panel handlers
  expressionNode.addEventListener('click', function(e) {
    e.preventDefault();
    expressionPanel.setAttribute('opacity', '1');
    expressionPanel.setAttribute('pointer-events', 'all');
  });

  // Rama/Tava Dasoham panel handlers
  ramaNode.addEventListener('click', function(e) {
    e.preventDefault();
    ramaPanel.setAttribute('opacity', '1');
    ramaPanel.setAttribute('pointer-events', 'all');
  });

  // Musical Legacy panel handlers
  const musicalLegacyNode = document.querySelector('.musical-legacy-node');
  const musicalLegacyPanel = document.getElementById('musical-legacy-panel');
