      ramaPanel.setAttribute('opacity', '0');
      ramaPanel.setAttribute('pointer-events', 'none');
      musicalLegacyPanel.setAttribute('opacity', '0');
      musicalLegacyPanel.setAttribute('pointer-events', 'none');
      giriPaiPanel.setAttribute('opacity', '0');
      giriPaiPanel.setAttribute('pointer-events', 'none');
      teraTeeyakaPanel.setAttribute('opacity', '0');
      teraTeeyakaPanel.setAttribute('pointer-events', 'none');
      guruLekaPanel.setAttribute('opacity', '0');
      guruLekaPanel.setAttribute('pointer-events', 'none');
    }, true);
  }

  if (closeBtnMusicalLegacy) {
    closeBtnMusicalLegacy.addEventListener('click', function(e) {
      e.stopPropagation();
      e.preventDefault();
      // Close ALL panels
      devotionPanel.setAttribute('opacity', '0');
      devotionPanel.setAttribute('pointer-events', 'none');
      expressionPanel.setAttribute('opacity', '0');
      expressionPanel.setAttribute('pointer-events', 'none');
      ramaPanel.setAttribute('opacity', '0');
      ramaPanel.setAttribute('pointer-events', 'none');
      musicalLegacyPanel.setAttribute('opacity', '0');
      musicalLegacyPanel.setAttribute('pointer-events', 'none');
      giriPaiPanel.setAttribute('opacity', '0');
      giriPaiPanel.setAttribute('pointer-events', 'none');
      teraTeeyakaPanel.setAttribute('opacity', '0');
      teraTeeyakaPanel.setAttribute('pointer-events', 'none');
      guruLekaPanel.setAttribute('opacity', '0');
      guruLekaPanel.setAttribute('pointer-events', 'none');
    }, true);
  }

  if (closeBtnTeraTeeyaka) {
    closeBtnTeraTeeyaka.addEventListener('click', function(e) {
      e.stopPropagation();
      e.preventDefault();
      // Close ALL panels
      devotionPanel.setAttribute('opacity', '0');
      devotionPanel.setAttribute('pointer-events', 'none');
      expressionPanel.setAttribute('opacity', '0');
      expressionPanel.setAttribute('pointer-events', 'none');
      ramaPanel.setAttribute('opacity', '0');
      ramaPanel.setAttribute('pointer-events', 'none');
      musicalLegacyPanel.setAttribute('opacity', '0');
      musicalLegacyPanel.setAttribute('pointer-events', 'none');
      giriPaiPanel.setAttribute('opacity', '0');
      giriPaiPanel.setAttribute('pointer-events', 'none');
      teraTeeyakaPanel.setAttribute('opacity', '0');
      teraTeeyakaPanel.setAttribute('pointer-events', 'none');
      guruLekaPanel.setAttribute('opacity', '0');
      guruLekaPanel.setAttribute('pointer-events', 'none');
    }, true);
  }

  if (closeBtnGiriPai) {
    closeBtnGiriPai.addEventListener('click', function(e) {
      e.stopPropagation();
      e.preventDefault();
      // Close ALL panels
      devotionPanel.setAttribute('opacity', '0');
      devotionPanel.setAttribute('pointer-events', 'none');
      expressionPanel.setAttribute('opacity', '0');
      expressionPanel.setAttribute('pointer-events', 'none');
      ramaPanel.setAttribute('opacity', '0');
      ramaPanel.setAttribute('pointer-events', 'none');
      musicalLegacyPanel.setAttribute('opacity', '0');
      musicalLegacyPanel.setAttribute('pointer-events', 'none');
      giriPaiPanel.setAttribute('opacity', '0');
      giriPaiPanel.setAttribute('pointer-events', 'none');
      teraTeeyakaPanel.setAttribute('opacity', '0');
      teraTeeyakaPanel.setAttribute('pointer-events', 'none');
      guruLekaPanel.setAttribute('opacity', '0');
      guruLekaPanel.setAttribute('pointer-events', 'none');
    }, true);
  }

  if (closeBtnGuruLeka) {
    closeBtnGuruLeka.addEventListener('click', function(e) {
      e.stopPropagation();
      e.preventDefault();
      // Close ALL panels
      devotionPanel.setAttribute('opacity', '0');
      devotionPanel.setAttribute('pointer-events', 'none');
      expressionPanel.setAttribute('opacity', '0');
      expressionPanel.setAttribute('pointer-events', 'none');
      ramaPanel.setAttribute('opacity', '0');
      ramaPanel.setAttribute('pointer-events', 'none');
      musicalLegacyPanel.setAttribute('opacity', '0');
      musicalLegacyPanel.setAttribute('pointer-events', 'none');
      giriPaiPanel.setAttribute('opacity', '0');
      giriPaiPanel.setAttribute('pointer-events', 'none');
      teraTeeyakaPanel.setAttribute('opacity', '0');
      teraTeeyakaPanel.setAttribute('pointer-events', 'none');
      guruLekaPanel.setAttribute('opacity', '0');
      guruLekaPanel.setAttribute('pointer-events', 'none');
    }, true);
  }
})();
